	(137, 3, 'THR-2721', 'Supply Chain Compromise (SolarWinds style)', 'Compromise of software update mechanism in CI/CD pipeline leading to downstream infection of customer environments.', 'Technical', 'External', 'Deliberate', 'Possible', 'Critical', '"\"Build Server, Release Pipeline, Customer Agents\""', '"\"CVE-2024-XYZ, CVE-2025-ABC\""', '"\"Reputational Damage, Legal Liability, Customer Churn\""', 'Attacker gains access to the build server via compromised developer credentials, injects malicious code into the update binary, which is then signed and distributed to 5000+ customers.', 'Binary Integrity Monitoring, Behavioral Analysis of Build Process', 'active', 'Head of DevOps', '2025-11-15 00:00:00', '2026-01-23 09:28:59.052331', '2026-01-23 09:28:59.052331'),
	(138, 3, 'THR-1190', 'Insider IP Theft', 'Privileged user (admin/developer) exfiltrating proprietary threat intelligence algorithms or source code to a competitor or foreign entity.', 'Human', 'Insider', 'Deliberate', 'Possible', 'High', '"\"Threat Intel DB, Source Code Repo, Confluence\""', '"\"Weak DLP Policies, Excessive Privileges\""', '"\"Loss of Competitive Advantage, IP Loss\""', 'Disgruntled engineer downloads the core "Predictive Engine" source code to a personal USB drive before resigning.', 'DLP Alerts, USB Blocking Logs, User Behavior Analytics (UBA)', 'active', 'CISO', '2025-12-01 00:00:00', '2026-01-23 09:28:59.157914', '2026-01-23 09:28:59.157914'),
	(139, 3, 'THR-8967', 'API Key Leakage', 'Accidental commit of production API keys or cloud credentials to public repositories (GitHub) or logs.', 'Technical', 'Internal', 'Accidental', 'Likely', 'High', '"\"AWS Production Environment, 3rd Party Integrations (Stripe, Twilio)\""', '"\"Missing Pre-commit Hooks, Lack of Secret Scanning\""', '"\"Cloud Resource Hijacking, Data Breach\""', 'Junior dev commits `.env` file containing AWS Admin keys to a public repo. Bots scrape it within 5 minutes and spin up crypto miners.', 'GitHub Secret Scanning, AWS GuardDuty', 'active', 'Lead Architect', '2026-01-10 00:00:00', '2026-01-23 09:28:59.261423', '2026-01-23 09:28:59.261423'),
	(140, 3, 'THR-4210', 'Ransomware - Double Extortion', 'Attackers encrypt production databases and threaten to leak sensitive customer data unless ransom is paid.', 'Technical', 'Hacker', 'Deliberate', 'Possible', 'Critical', '"\"Customer DB, File Servers, Backup Systems\""', '"\"Unpatched VPN Gateway, Weak RDP Passwords\""', '"\"Operational Downtime, Financial Loss, Regulatory Fines\""', 'Attackers gain initial access via phishing, move laterally to DC, exfiltrate data, then deploy encryption across all Windows servers.', 'EDR Alerts, Network Traffic Anomaly (Data Exfil)', 'active', 'SecOps Lead', '2025-10-20 00:00:00', '2026-01-23 09:28:59.365394', '2026-01-23 09:28:59.365394'),
